package com.htttdn.crm.service;

import com.htttdn.crm.entity.User;
import jakarta.persistence.EntityManager;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import java.time.Instant;
import java.util.UUID;
import static org.junit.jupiter.api.Assertions.*;

@EnabledIfEnvironmentVariable(named="CRM_POSTGRES_QA",matches="true")
@SpringBootTest(properties={"spring.jpa.hibernate.ddl-auto=none","crm.care-reminders.enabled=false"}) @Transactional
class SupportTicketPostgresTest {
    @Autowired EntityManager em;@Autowired JdbcTemplate db;@Autowired SupportTicketService service;@Autowired ManagerCareInbox inbox;
    User user(String role){var u=new User();u.setFullName("Support PostgreSQL QA");u.setEmail(UUID.randomUUID()+"@qa.test");u.setPasswordHash("test-not-login");u.setRole(role);em.persist(u);em.flush();return u;}
    @Test void postgresTicketConversationAuditAndNotificationsUseTemporaryRollbackFixtures(){
        // Only transaction-local temporary tables are modified. No migration or public-table writes.
        db.execute("create temporary table customers (like public.customers including all) on commit drop");
        db.execute("alter table customers alter column customer_id drop default");
        db.execute("alter table customers alter column customer_id add generated by default as identity");
        db.execute("create temporary table orders (like public.orders including all) on commit drop");
        db.execute("create temporary table customer_care_tasks(id bigint primary key,customer_id bigint,assignee_id bigint,status varchar(30),due_at timestamptz) on commit drop");
        db.execute("create temporary table audit_logs(id bigserial primary key,actor_id bigint,actor_name varchar(150),actor_role varchar(20),action varchar(40),entity_type varchar(40),target_id bigint,before_data text,after_data text,created_at timestamptz) on commit drop");
        db.execute("create temporary table support_tickets(id bigserial primary key,customer_id bigint references customers(customer_id),order_id bigint references orders(order_id),assignee_id bigint references customers(customer_id),created_by bigint references customers(customer_id),request_key varchar(36),title varchar(150),description varchar(4000),status varchar(30),messages text,created_at timestamptz,updated_at timestamptz,resolved_at timestamptz,version bigint,unique(created_by,request_key)) on commit drop");
        db.execute("create temporary table customer_notifications(id bigserial primary key,customer_id bigint references customers(customer_id),title varchar(150),content varchar(2000),type varchar(30),order_id bigint,care_task_id bigint,care_due_at timestamptz,support_ticket_id bigint references support_tickets(id),created_at timestamptz,read_at timestamptz) on commit drop");
        var buyer=user("CUSTOMER");var manager=user("MANAGER");var customer=new SupportTicketService.Actor(buyer.getId(),false);var staff=new SupportTicketService.Actor(manager.getId(),true);
        var input=new SupportTicketService.Create(null,null,null,"Postgres support","Description",UUID.randomUUID().toString());var ticket=service.create(customer,input).ticket();assertEquals(ticket.id(),service.create(customer,input).ticket().id());
        ticket=service.update(staff,ticket.id(),new SupportTicketService.Update(manager.getId(),"IN_PROGRESS",ticket.version(),"",null)).ticket();assertEquals(1,inbox.unread(manager.getId(),Instant.now()));
        service.reply(staff,ticket.id(),new SupportTicketService.Reply("Private note",true,UUID.randomUUID().toString()));assertTrue(service.detail(customer,ticket.id()).messages().isEmpty());
        ticket=service.detail(staff,ticket.id()).ticket();service.update(staff,ticket.id(),new SupportTicketService.Update(manager.getId(),"WAITING_CUSTOMER",ticket.version(),"Please clarify",UUID.randomUUID().toString()));
        service.reply(customer,ticket.id(),new SupportTicketService.Reply("Details",false,UUID.randomUUID().toString()));ticket=service.detail(staff,ticket.id()).ticket();assertEquals("IN_PROGRESS",ticket.status());
        assertEquals(1,service.list(staff,"Postgres","IN_PROGRESS",buyer.getId(),manager.getId(),0,10).totalElements());
        service.update(staff,ticket.id(),new SupportTicketService.Update(manager.getId(),"RESOLVED",ticket.version(),"Resolved",UUID.randomUUID().toString()));assertEquals(0,inbox.unread(manager.getId(),Instant.now()));
        assertEquals(4,db.queryForObject("select count(*) from audit_logs",Long.class));assertEquals(1,db.queryForObject("select count(*) from support_tickets",Long.class));
    }
}
